// ============================================================================
// Module:       strobe_app::ui::credits
// Description:  The About page's credits: the source and licence, the
//               contributors, the projects Strobe is built on, what it plays
//               and imports, and every crate in the program with its licence.
//
// Dependencies: egui; super::{form, theme, widgets}, crate::palette;
//               THIRD_PARTY.md (generated by `cargo xtask credits`)
// ============================================================================

//! Credits, on Settings > About (D491).
//!
//! The people and the crates are not a list kept here: `cargo xtask
//! credits` writes `THIRD_PARTY.md` at the repository root from the git
//! history and `Cargo.lock`, CI fails when it is stale, and this module
//! compiles it in and reads its tables once ([`credits`]). What is written
//! here is the part a generator cannot know: which projects matter most and
//! what each does for Strobe ([`UPSTREAM`]). Their licences still come from
//! the generated table, and a test fails if one of them leaves the build.
//!
//! The page stays in the form grammar: a group per subject, a row per
//! credit, its licence or a link in the control column. Links are quiet
//! buttons that open the browser (egui-winit's `links`), never accent text
//! scattered through the descriptions (branding.md section 6). The full crate
//! list is folded under one row, so the page opens short.

use super::form::{self, Row};
use super::theme::{self, SPACE_SM};
use super::widgets;
use crate::palette::Palette;
use egui::Ui;
use std::sync::OnceLock;

/// The repository, from the workspace manifest.
const REPOSITORY: &str = env!("CARGO_PKG_REPOSITORY");

/// The generated list: contributors, what ships beside the program, and
/// every crate in it.
const THIRD_PARTY: &str = include_str!("../../../../THIRD_PARTY.md");

/// The source row's title, which search finds.
pub const SOURCE: &str = "Source code";
/// The licence row's title, which search finds.
pub const LICENCE: &str = "Licence";
/// The crate list's row title, which search finds.
pub const CRATES: &str = "Every crate";

/// One project Strobe is built on.
struct Upstream {
    /// Its name as people know it.
    title: &'static str,
    /// What it does for Strobe, in a line.
    role: &'static str,
    /// The crates it is, whose licences the generated table gives. Empty
    /// for what is not a crate.
    crates: &'static [&'static str],
    /// The licence of what is not a crate, or of the C library a crate
    /// wraps.
    licence: Option<&'static str>,
}

/// The projects Strobe stands on, in the order a frame meets them.
const UPSTREAM: &[Upstream] = &[
    Upstream {
        title: "egui",
        role: "The control window's widgets and layout, through egui-winit and egui_glow.",
        crates: &["egui", "egui-winit", "egui_glow"],
        licence: None,
    },
    Upstream {
        title: "glow",
        role: "The OpenGL bindings every scene is compiled and drawn through.",
        crates: &["glow"],
        licence: None,
    },
    Upstream {
        title: "glutin and winit",
        role: "The windows, their input, and the OpenGL context, native or through ANGLE.",
        crates: &["glutin", "winit"],
        licence: None,
    },
    Upstream {
        title: "ANGLE",
        role: "Google's OpenGL ES on Direct3D 11 or Vulkan, for a machine whose OpenGL driver \
               fails. Its DLLs ship beside strobe.exe, taken from an Electron release.",
        crates: &[],
        licence: Some("BSD-3-Clause"),
    },
    Upstream {
        title: "QuickJS-ng",
        role: "The JavaScript engine scene scripts run in, through the rquickjs crate.",
        crates: &["rquickjs"],
        licence: None,
    },
    Upstream {
        title: "cpal, RustFFT and RealFFT",
        role: "Audio from the sound card, and the spectrum scenes react to.",
        crates: &["cpal", "rustfft", "realfft"],
        licence: None,
    },
    Upstream {
        title: "serde and toml",
        role: "Reading and writing scenes, playlists and settings.",
        crates: &["serde", "serde_json", "toml"],
        licence: None,
    },
    Upstream {
        title: "midir and rosc",
        role: "MIDI and OSC show control.",
        crates: &["midir", "rosc"],
        licence: None,
    },
    Upstream {
        title: "rfd",
        role: "The native file and folder pickers.",
        crates: &["rfd"],
        licence: None,
    },
    Upstream {
        title: "ureq and rustls",
        role: "Shadertoy import over HTTPS, with no OpenSSL.",
        crates: &["ureq", "rustls"],
        licence: None,
    },
    Upstream {
        title: "crash-handler and minidumper",
        role: "The crash reports a failed show can be traced from.",
        crates: &["crash-handler", "minidumper"],
        licence: None,
    },
];

/// A crate in the program.
struct Crate {
    name: &'static str,
    licence: &'static str,
}

/// [`THIRD_PARTY`] read, with the lines drawn from it made once.
struct Credits {
    /// (name, role), the author first.
    people: Vec<(&'static str, &'static str)>,
    crates: Vec<Crate>,
    /// Each [`UPSTREAM`] entry's licence.
    licences: Vec<String>,
    /// The crate row's description, which names the count.
    summary: String,
    /// Where the licence and the generated list are read online.
    licence_url: String,
    list_url: String,
}

/// Whether the crate list is open: egui's memory, not the app's state, as
/// a folded section is (it is not saved, and nothing else reads it).
fn open_id() -> egui::Id {
    egui::Id::unique("credits-crates-open")
}

/// The rows of each `## heading`'s table in `text`, without the header and
/// the rule under it: `(heading, cells)`.
fn tables(text: &'static str) -> Vec<(&'static str, Vec<&'static str>)> {
    let mut rows = Vec::new();
    let mut heading = "";
    let mut header_seen = false;
    for line in text.lines() {
        if let Some(title) = line.strip_prefix("## ") {
            heading = title.trim();
            header_seen = false;
            continue;
        }
        let Some(inner) = line
            .trim()
            .strip_prefix('|')
            .and_then(|line| line.strip_suffix('|'))
        else {
            continue;
        };
        if inner.starts_with("---") {
            continue;
        }
        if !header_seen {
            header_seen = true;
            continue;
        }
        rows.push((heading, inner.split('|').map(str::trim).collect()));
    }
    rows
}

/// The credits, read from [`THIRD_PARTY`] the first time they are drawn.
fn credits() -> &'static Credits {
    static CREDITS: OnceLock<Credits> = OnceLock::new();
    CREDITS.get_or_init(|| {
        let mut people = Vec::new();
        let mut crates = Vec::new();
        for (heading, cells) in tables(THIRD_PARTY) {
            match (heading, cells.as_slice()) {
                ("Contributors", [name, role, ..]) => people.push((*name, *role)),
                ("Crates", [name, licence, ..]) => crates.push(Crate { name, licence }),
                _ => {}
            }
        }
        let licences = UPSTREAM
            .iter()
            .map(|upstream| {
                let mut found: Vec<&str> = Vec::new();
                let named = upstream
                    .crates
                    .iter()
                    .filter_map(|name| crates.iter().find(|c| c.name == *name))
                    .map(|c| c.licence);
                for licence in named.chain(upstream.licence) {
                    if !found.contains(&licence) {
                        found.push(licence);
                    }
                }
                // A dot, not a comma, between projects: a licence
                // expression is itself a list of names joined by words.
                found.join(" · ")
            })
            .collect();
        let summary = format!(
            "The {} crates compiled into strobe.exe, each with the licence its authors chose. \
             The release zip's THIRD-PARTY-NOTICES.txt has every licence in full.",
            crates.len()
        );
        Credits {
            people,
            crates,
            licences,
            summary,
            licence_url: format!("{REPOSITORY}/blob/master/LICENSE"),
            list_url: format!("{REPOSITORY}/blob/master/THIRD_PARTY.md"),
        }
    })
}

/// A link: a quiet button that opens `url` in the browser.
fn link(ui: &mut Ui, theme: &Palette, label: &str, url: &str) {
    if widgets::button(ui, theme, None, label)
        .on_hover_text(url)
        .clicked()
    {
        ui.ctx().open_url(egui::OpenUrl::new_tab(url));
    }
}

/// A licence in a row's control column: quiet, and wrapped if long.
fn licence(ui: &mut Ui, theme: &Palette, text: &str) {
    ui.add(
        egui::Label::new(
            egui::RichText::new(text)
                .font(theme::description_font())
                .color(theme::rgb(theme.text_muted)),
        )
        .wrap(),
    );
}

/// The source and licence rows, for the page's first group.
pub fn project(group: &mut form::Group<'_>, theme: &Palette) {
    group.row(
        Row::new(SOURCE).description("The code, the releases, and where to report a bug."),
        |ui| link(ui, theme, "GitHub", REPOSITORY),
    );
    group.row(
        Row::new(LICENCE).description(
            "MIT with the Commons Clause: use it, change it and perform with it, paid shows \
             included. Selling Strobe itself is not allowed.",
        ),
        |ui| link(ui, theme, "Read", &credits().licence_url),
    );
}

/// The groups after the build: contributors, what Strobe is built on, what
/// it plays and imports, and every crate.
pub fn show(ui: &mut Ui, theme: &Palette) {
    let credits = credits();
    form::group(ui, theme, "Contributors", |group| {
        for (name, role) in &credits.people {
            group.row(Row::new(name).description(role), |_| {});
        }
    });
    form::group(ui, theme, "Built on", |group| {
        for (upstream, text) in UPSTREAM.iter().zip(&credits.licences) {
            group.row(Row::new(upstream.title).description(upstream.role), |ui| {
                licence(ui, theme, text);
            });
        }
    });
    form::group(ui, theme, "Formats", |group| {
        group.row(
            Row::new("Synesthesia").description(
                "Strobe plays scenes in Synesthesia's SSF format and follows its documented \
                 behaviour. It is an independent project, not affiliated with or endorsed by \
                 Synesthesia.",
            ),
            |ui| link(ui, theme, "synesthesia.live", "https://synesthesia.live"),
        );
        group.row(
            Row::new("Shadertoy").description(
                "Import brings shaders in from shadertoy.com and keeps each author's name and \
                 licence note with the scene.",
            ),
            |ui| link(ui, theme, "shadertoy.com", "https://www.shadertoy.com"),
        );
    });
    form::group(ui, theme, "Crates", |group| {
        let mut open = group
            .ui()
            .data(|data| data.get_temp(open_id()).unwrap_or(false));
        // The column fills from the right: Show, the row's own action,
        // sits at the edge, the link beside it.
        group.row(Row::new(CRATES).description(&credits.summary), |ui| {
            let word = if open { "Hide" } else { "Show" };
            if widgets::button(ui, theme, None, word).clicked() {
                open = !open;
            }
            link(ui, theme, "GitHub", &credits.list_url);
        });
        group
            .ui()
            .data_mut(|data| data.insert_temp(open_id(), open));
        if open {
            group.block(|ui| {
                for each in &credits.crates {
                    ui.horizontal_wrapped(|ui| {
                        ui.spacing_mut().item_spacing.x = SPACE_SM;
                        ui.label(
                            egui::RichText::new(each.name)
                                .font(theme::description_font())
                                .color(theme::rgb(theme.text)),
                        );
                        ui.label(
                            egui::RichText::new(each.licence)
                                .font(theme::description_font())
                                .color(theme::rgb(theme.text_muted)),
                        );
                    });
                }
            });
        }
    });
}

/// Opens the crate list, as a click on Show would: for the shell's tests.
#[cfg(test)]
pub(super) fn open_crates(ctx: &egui::Context) {
    ctx.data_mut(|data| data.insert_temp(open_id(), true));
}

#[cfg(test)]
mod tests {
    use super::*;
    use anyhow::Result;

    #[test]
    fn the_generated_list_names_people_and_crates() {
        let credits = credits();
        assert!(
            credits
                .people
                .first()
                .is_some_and(|(_, role)| *role == "Author and maintainer"),
            "the author leads the contributors: {:?}",
            credits.people
        );
        assert!(
            credits.people.iter().all(|(name, _)| !name.contains('@')),
            "no addresses: {:?}",
            credits.people
        );
        assert!(
            credits.crates.len() > 100 && credits.crates.iter().all(|c| !c.licence.is_empty()),
            "every crate with a licence, and plenty of them: {}",
            credits.crates.len()
        );
    }

    #[test]
    fn every_project_credited_is_in_the_build() -> Result<()> {
        let credits = credits();
        for upstream in UPSTREAM {
            for name in upstream.crates {
                anyhow::ensure!(
                    credits.crates.iter().any(|c| c.name == *name),
                    "{} credits {name}, which strobe.exe no longer links",
                    upstream.title
                );
            }
        }
        for (upstream, text) in UPSTREAM.iter().zip(&credits.licences) {
            assert!(!text.is_empty(), "{} has a licence", upstream.title);
        }
        Ok(())
    }

    #[test]
    fn a_table_skips_its_header_and_rule() {
        let rows = tables("## A\n\n| H | I |\n|---|---|\n| x | y |\n## B\n| H |\n|---|\n| z |\n");
        assert_eq!(
            rows,
            vec![("A", vec!["x", "y"]), ("B", vec!["z"])],
            "rows under their heading"
        );
    }
}
